SELECT jsonb_build_object(
'context', jsonb_build_object('server_version',current_setting('server_version'),'search_path',current_setting('search_path')),
'enums', (SELECT coalesce(jsonb_agg(x ORDER BY x.name),'[]') FROM (SELECT t.typname AS name, jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) AS labels FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' GROUP BY t.typname) x),
'tables', (SELECT coalesce(jsonb_agg(x ORDER BY x.name),'[]') FROM (SELECT c.relname AS name, c.relrowsecurity AS rls, c.relforcerowsecurity AS force_rls, c.reloptions, (SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated::text,'identity',a.attidentity::text) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) AS columns FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r') x),
'constraints', (SELECT coalesce(jsonb_agg(x ORDER BY x.kind,x.table_name,x.name),'[]') FROM (SELECT c.relname AS table_name,k.conname AS name,k.contype::text AS kind,pg_get_constraintdef(k.oid,true) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public') x),
'functions', (SELECT coalesce(jsonb_agg(x ORDER BY x.signature),'[]') FROM (SELECT p.oid::regprocedure::text AS signature,pg_get_function_identity_arguments(p.oid) AS arguments,p.proname AS name,p.prokind::text AS kind,pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN ('f','p') AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid=p.oid AND d.classid='pg_proc'::regclass AND d.deptype='e')) x),
'views', (SELECT coalesce(jsonb_agg(x ORDER BY x.name),'[]') FROM (SELECT c.relname AS name,pg_get_viewdef(c.oid,true) AS definition,c.reloptions FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v') x),
'indexes', (SELECT coalesce(jsonb_agg(x ORDER BY x.name),'[]') FROM (SELECT i.relname AS name,pg_get_indexdef(i.oid) AS definition FROM pg_index k JOIN pg_class i ON i.oid=k.indexrelid JOIN pg_class c ON c.oid=k.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT EXISTS(SELECT 1 FROM pg_constraint z WHERE z.conindid=i.oid)) x),
'triggers', (SELECT coalesce(jsonb_agg(x ORDER BY x.table_name,x.name),'[]') FROM (SELECT c.relname AS table_name,t.tgname AS name,pg_get_triggerdef(t.oid,true) AS definition,t.tgenabled::text AS enabled FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal) x),
'policies', (SELECT coalesce(jsonb_agg(x ORDER BY x.table_name,x.name),'[]') FROM (SELECT tablename AS table_name,policyname AS name,permissive,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public') x),
'relation_grants', (SELECT coalesce(jsonb_agg(x ORDER BY x.table_name,x.role,x.privilege),'[]') FROM (SELECT c.relname AS table_name,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS role,a.privilege_type AS privilege,a.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='public' AND c.relkind IN ('r','v')) x),
'column_grants', (SELECT coalesce(jsonb_agg(x ORDER BY x.table_name,x.column_name,x.role,x.privilege),'[]') FROM (SELECT c.relname AS table_name,a.attname AS column_name,CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END AS role,g.privilege_type AS privilege,g.is_grantable FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(a.attacl) g WHERE n.nspname='public' AND c.relkind IN ('r','v') AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL) x),
'function_grants', (SELECT coalesce(jsonb_agg(x ORDER BY x.signature,x.role),'[]') FROM (SELECT p.oid::regprocedure::text AS signature,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS role,a.privilege_type AS privilege,a.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.objid=p.oid AND d.classid='pg_proc'::regclass AND d.deptype='e')) x),
'extensions', (SELECT jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)
) AS catalog;
